parameters.jsCode:
// Construction de l'URL complète, une par liaison.
// Les paramètres sont assemblés ici plutôt que dans le nœud HTTP : cela
// permet de conserver l'URL exacte appelée dans la référence d'audit, et
// d'éviter la configuration statique de paramètres de requête, qui
// obligerait à un nœud HTTP par source — exactement ce que ce workflow
// supprime.
const runId = $('Ouvrir le run').first().json.run_id;
const sortie = [];

for (const item of $input.all()) {
  const b = item.json;
  const params = typeof b.params === 'string' ? JSON.parse(b.params) : (b.params ?? {});
  const mapping = typeof b.mapping === 'string' ? JSON.parse(b.mapping) : (b.mapping ?? {});

  // Transport déclaré par la liaison : les clés réservées _methode et _corps
  // ne sont PAS des paramètres de requête. Ajouté le 17.08.2026 pour les
  // sources en POST (OFS PX-Web) — le corps vit dans source_bindings.params,
  // donc au référentiel, donc auditable comme le reste de la liaison.
  const methode = String(params._methode ?? 'GET').toUpperCase();
  const corpsRequete = params._corps ?? null;
  const qs = Object.entries(params)
    .filter(([k]) => !k.startsWith('_'))
    .map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(String(v)))
    .join('&');
  const url = qs ? b.url_base + (b.url_base.includes('?') ? '&' : '?') + qs : b.url_base;

  sortie.push({ json: {
    methode,
    corps_requete: corpsRequete,
    binding_id: b.binding_id,
    indicator_id: b.indicator_id,
    connecteur: b.connecteur,
    geo_defaut: b.geo_defaut,
    mapping,
    url_complete: url,
    run_id: runId,
    raw_ref: '/data/staging/' + b.indicator_id + '_run' + runId + '.raw'
  } });
}

if (sortie.length === 0) {
  throw new Error("Aucune liaison active : rien à collecter. Vérifier que source_bindings contient au moins une ligne au statut 'actif'.");
}
return sortie;

// Réassociation réponse <-> liaison par pairedItem, et non plus par position.
// La scission Comtrade / générique répartit les items entre deux nœuds d'appel ;
// l'appariement positionnel ne tiendrait plus. Chaque item porte le lien vers sa
// liaison d'origine (pairedItem) : on lit la liaison correspondante directement,
// quel que soit le nœud d'appel emprunté et quel que soit l'ordre.
const l = $('Préparer les appels').item.json;
const r = $json;
const corps = r.data ?? r.body ?? null;

// Sérialisation lisible de l'erreur. Un objet passé à String() donne
// « [object Object] » : l'incident est consigné au run sans rien apprendre,
// et le diagnostic se fait à l'aveugle. On extrait le code HTTP quand il est
// disponible, puis le message le plus explicite que porte l'objet d'erreur.
let erreur = null;
const e = r.error;
if (e) {
  const detail = typeof e === 'string'
    ? e
    : (e.message || e.description || e.reason || JSON.stringify(e));
  const code = (e && typeof e === 'object' && (e.httpCode || e.status || e.statusCode))
    ? '[HTTP ' + (e.httpCode || e.status || e.statusCode) + '] '
    : '';
  erreur = (code + detail).slice(0, 300);
} else if (corps === null) {
  erreur = 'réponse vide';
}

return { json: { ...l, corps, erreur } };

// Décodage selon le connecteur déclaré par la liaison.
// Un connecteur inconnu ne produit rien et n'invente rien : il est compté
// comme échec et consigné à la clôture du run.
const liaisons = $('Réapparier réponses et liaisons').all().map(i => i.json);
const observations = [];
// Deux journaux distincts, et la distinction n'est pas cosmétique.
// Un INCIDENT est une défaillance : une source injoignable, un décodage
// impossible, une liaison sans effet. Il déclasse le run.
// Une TRACE est un fonctionnement normal qui mérite d'être consigné,
// comme une agrégation appliquée. Elle ne déclasse rien.
// Les confondre ferait marquer « partiel » un run parfaitement réussi —
// c'est-à-dire mentir sur son propre état, dans l'autre sens.
const incidents = [];
const traces = [];

function decodeEurostat(l) {
  const m = l.mapping ?? {};
  const resp = JSON.parse(l.corps);
  const valeurs = resp.value ?? {};
  const dims = resp.id ?? [];
  const tailles = resp.size ?? [];
  // Identifiants de dimensions surchargables par la liaison : Eurostat nomme
  // time/geo, l'OFS PX-Web (même format JSON-stat) nomme ses dimensions
  // selon la table. Ajouté le 17.08.2026 pour H2/M4. Sans surcharge,
  // comportement Eurostat inchangé.
  const posTemps = dims.indexOf(m.dim_temps ?? 'time');
  const posGeo = dims.indexOf(m.dim_geo ?? 'geo');
  if (posTemps < 0) throw new Error('réponse sans dimension temporelle');

  const libelles = (d) => {
    const idx = resp.dimension?.[d]?.category?.index ?? {};
    return Object.keys(idx).sort((a, b) => idx[a] - idx[b]);
  };
  const periodes = libelles('time');
  const zones = libelles('geo');

  const coord = (plat) => {
    const c = new Array(tailles.length);
    for (let d = tailles.length - 1; d >= 0; d--) { c[d] = plat % tailles[d]; plat = Math.floor(plat / tailles[d]); }
    return c;
  };

  const out = [];
  for (const [cle, v] of Object.entries(valeurs)) {
    if (v === null || v === undefined) continue;   // Eurostat laisse des trous : ils restent des trous
    const c = coord(Number(cle));
    const periode = periodes[c[posTemps]];
    if (!periode) continue;
    const zone = posGeo >= 0 ? (zones[c[posGeo]] ?? l.geo_defaut) : l.geo_defaut;
    out.push({ period: periode, geo: zone, value: Number(v) });
  }
  return out;
}

// Lecture CSV paramétrable. Trois réglages sont nécessaires parce que les
// producteurs de statistiques ne publient pas au même format : le séparateur
// (la virgule anglo-saxonne, le point-virgule des sources suisses et
// européennes), le nombre de lignes de métadonnées à sauter avant l'en-tête
// (la BNS en place trois), et l'encodage éventuel d'un BOM en tête de fichier.
function lignesCsv(texte, m) {
  const sep = m.separateur ?? ',';
  const saut = Number(m.sauter_lignes ?? 0);
  const propre = texte.replace(/^\uFEFF/, '');
  const lignes = propre.split(/\r?\n/).slice(saut).filter(x => x.trim() !== '');
  if (lignes.length < 2) throw new Error('CSV vide ou en-tête introuvable après ' + saut + ' ligne(s) sautée(s)');
  const decoupe = (ligne) => {
    const champs = []; let cur = ''; let guill = false;
    for (let i = 0; i < ligne.length; i++) {
      const ch = ligne[i];
      if (ch === '"') { if (guill && ligne[i + 1] === '"') { cur += '"'; i++; } else { guill = !guill; } }
      else if (ch === sep && !guill) { champs.push(cur); cur = ''; }
      else { cur += ch; }
    }
    champs.push(cur); return champs;
  };
  const entetes = decoupe(lignes[0]).map(h => h.trim().replace(/^"|"$/g, ''));
  return lignes.slice(1).map(l => {
    const c = decoupe(l);
    const o = {}; entetes.forEach((h, i) => { o[h] = (c[i] ?? '').trim().replace(/^"|"$/g, ''); });
    return o;
  });
}

function decodeCsv(l) {
  const m = l.mapping ?? {};
  const cEnt = m.colonne_entite, cPer = m.colonne_periode, cVal = m.colonne_valeur, cCode = m.colonne_code;
  if (!cPer || !cVal) throw new Error('mapping incomplet : colonne_periode et colonne_valeur sont requises');
  const retenues = Array.isArray(m.entites_retenues) ? m.entites_retenues : null;
  const perMin = m.periode_min ?? null;
  // Filtres additionnels : { "colonne": ["valeurs", "admises"] }. Nécessaire dès
  // qu'un fichier empile plusieurs séries — la BNS livre dans un même cube les
  // moyennes et les fins de mois, pour toutes les devises.
  const filtres = (m.filtres && typeof m.filtres === 'object') ? m.filtres : {};
  // Étiquetage de la zone quand elle ne figure pas en colonne mais dans le
  // choix de série : { "colonne": { "valeur_source": "CODE_ZONE" } }.
  const geoDepuis = (m.geo_depuis && typeof m.geo_depuis === 'object') ? m.geo_depuis : null;

  const out = [];
  for (const r of lignesCsv(l.corps, m)) {
    if (retenues && cEnt && !retenues.includes(r[cEnt])) continue;
    let exclue = false;
    for (const [col, admises] of Object.entries(filtres)) {
      if (!Array.isArray(admises) || !admises.includes(r[col])) { exclue = true; break; }
    }
    if (exclue) continue;
    const periode = String(r[cPer] ?? '').trim();
    if (!periode) continue;
    if (perMin && periode < perMin) continue;
    const brut = String(r[cVal] ?? '').trim();
    if (brut === '') continue;
    const valeur = Number(brut.replace(/\s/g, '').replace(',', '.'));
    if (!Number.isFinite(valeur)) continue;
    let zone = l.geo_defaut;
    if (geoDepuis) {
      const [col, table] = Object.entries(geoDepuis)[0];
      zone = table[r[col]] ?? l.geo_defaut;
    } else if (cCode && r[cCode]) zone = r[cCode];
    else if (cEnt && r[cEnt]) zone = r[cEnt] === 'World' ? 'WORLD' : r[cEnt];
    out.push({ period: periode, geo: zone, value: valeur });
  }
  return out;
}

function decodeJson(l) {
  const m = l.mapping ?? {};
  let noeud = JSON.parse(l.corps);
  const chemin = m.chemin_donnees ?? '';
  for (const seg of chemin.split('.').filter(Boolean)) {
    const idx = seg.match(/^\[(\d+)\]$/);
    noeud = idx ? noeud[Number(idx[1])] : noeud[seg];
    if (noeud === undefined) throw new Error('chemin_donnees introuvable : ' + chemin);
  }
  const perMin = m.periode_min ?? null;
  const perMax = m.periode_max ?? null;
  // Normalisation de la période selon format_periode. Comtrade renvoie les
  // périodes mensuelles en entier AAAAMM (ex. 202401) ; les contrôles qualité
  // valident ^\d{4}(-(\d{2}|T\d|S\d))?$ et rejetteraient 202401. On traduit
  // 202401 -> 2024-01. Sans format_periode, la période est laissée telle quelle.
  const fmtPeriode = (p) => {
    const s = String(p ?? '').trim();
    if (m.format_periode === 'AAAAMM' && /^\d{6}$/.test(s)) return s.slice(0,4) + '-' + s.slice(4,6);
    return s;
  };
  // Mode « objet indexé par période » : le nœud est un dictionnaire
  // { "2023": 3.3, "2024": 3.4, ... } et non une liste. Nécessaire pour le
  // FMI (DataMapper), qui imbrique les valeurs par année sous le code de
  // l'économie. Activé par le drapeau objet_par_periode du mapping. Les bornes
  // periode_min/periode_max permettent d'écarter les projections des réalisés.
  if (m.objet_par_periode && noeud && typeof noeud === 'object' && !Array.isArray(noeud)) {
    const out = [];
    for (const [periode, brut] of Object.entries(noeud)) {
      const per = fmtPeriode(periode);
      if (!per) continue;
      if (perMin && per < perMin) continue;
      if (perMax && per > perMax) continue;
      if (brut === null || brut === undefined || brut === '') continue;
      const valeur = Number(brut);
      if (!Number.isFinite(valeur)) continue;
      out.push({ period: per, geo: l.geo_defaut, value: valeur });
    }
    return out;
  }
  if (!Array.isArray(noeud)) throw new Error('chemin_donnees ne pointe pas sur une liste');
  const out = [];
  for (const r of noeud) {
    const periode = fmtPeriode(r[m.colonne_periode]);
    const brut = r[m.colonne_valeur];
    if (!periode || brut === null || brut === undefined || brut === '') continue;
    const valeur = Number(brut);
    if (!Number.isFinite(valeur)) continue;
    let zone = m.colonne_geo ? (r[m.colonne_geo] || l.geo_defaut) : l.geo_defaut;
    // Renommage de zone déclaré par la liaison — symétrique du geo_depuis du
    // décodeur CSV : { "valeur_source": "CODE_ZONE" }. Ajouté le 17.08.2026
    // pour M3 : l'agrégat mondial GHO s'appelle GLOBAL, le registre l'attend
    // en WORLD. Sans renommage, aucun run correctif ne peut superseder une
    // ligne WORLD erronée — le dernier point WORLD resterait faux à jamais.
    if (m.geo_renommage && typeof m.geo_renommage === 'object' && (String(zone) in m.geo_renommage)) zone = m.geo_renommage[String(zone)];
    if (!zone) continue;
    out.push({ period: periode, geo: String(zone), value: valeur });
  }
  return out;
}

for (const l of liaisons) {
  if (l.erreur) { incidents.push(l.indicator_id + ' : appel en échec (' + l.erreur + ')'); continue; }
  try {
    let brutes;
    if (l.connecteur === 'eurostat_jsonstat')                       brutes = decodeEurostat(l);
    else if (l.connecteur === 'owid_csv' || l.connecteur === 'csv_generique') brutes = decodeCsv(l);
    else if (l.connecteur === 'json_generique')                     brutes = decodeJson(l);
    else throw new Error('connecteur inconnu : ' + l.connecteur);

    // Agrégation explicite, demandée par la liaison et jamais implicite.
    // Certaines réponses sont ventilées sur une dimension que l'indicateur
    // ne distingue pas : M1 interroge cinq positions SH (9018 à 9022) et
    // reçoit une ligne par position et par déclarant. Sans somme, les cinq
    // lignes partagent la clé (indicateur, run, période, zone) et la
    // contrainte d'unicité n'en conserve qu'une — silencieusement. La
    // valeur affichée serait alors une position sur cinq, d'apparence
    // parfaitement crédible. La somme est calculée ici, de manière
    // déterministe, et le nombre de lignes fusionnées est consigné.
    if (l.mapping && l.mapping.agreger === 'somme') {
      const avant = brutes.length;
      const parCle = new Map();
      for (const o of brutes) {
        const cle = o.period + '|' + o.geo;
        parCle.set(cle, (parCle.get(cle) ?? 0) + o.value);
      }
      brutes = [...parCle.entries()].map(([cle, somme]) => {
        const sep = cle.indexOf('|');
        return { period: cle.slice(0, sep), geo: cle.slice(sep + 1), value: somme };
      });
      traces.push(l.indicator_id + ' : agrégation par somme, ' + avant + ' ligne(s) fusionnée(s) en ' + brutes.length);
    }

    if (brutes.length === 0) { incidents.push(l.indicator_id + ' : aucune observation décodée'); continue; }

    for (const o of brutes) {
      observations.push({ json: {
        indicator_id: l.indicator_id,
        run_id: l.run_id,
        period: o.period,
        geo: o.geo,
        value: o.value,
        obtained_by: 'etl',
        validation_status: 'valide_source',
        raw_ref: l.raw_ref
      } });
    }
  } catch (e) {
    incidents.push(l.indicator_id + ' : décodage impossible (' + String(e.message).slice(0, 200) + ')');
  }
}

// Une exécution sans observation n'interrompt PAS la chaîne : elle est
// consignée. Le comportement précédent — lever une exception — faisait
// mourir la branche en silence et produisait une note de run fausse,
// annonçant moins d'incidents qu'il n'y en avait eu. Un bilan d'exécution
// inexact est plus grave qu'une collecte vide : il empêche de savoir que
// la collecte a été vide.
if (observations.length === 0) {
  incidents.push('AUCUNE observation décodée sur ' + liaisons.length + ' liaison(s) traitée(s)');
  return [{ json: { _aucune_observation: true, _liaisons_traitees: liaisons.map(l => l.indicator_id), _incidents: incidents, _traces: traces } }];
}

// Contrôle de complétude : toute liaison qui ne produit ni observation ni
// incident est signalée nommément. Sans lui, une liaison peut disparaître
// du bilan sans laisser de trace — c'est ce qui s'est produit le 09.08.2026.
const avecDonnees = new Set(observations.map(o => o.json.indicator_id));
for (const l of liaisons) {
  const cite = incidents.some(i => i.startsWith(l.indicator_id + ' :'));
  if (!avecDonnees.has(l.indicator_id) && !cite) {
    incidents.push(l.indicator_id + ' : aucune donnée et aucune erreur — liaison sans effet, à instruire');
  }
}

return observations.map(o => ({ json: { ...o.json, _incidents: incidents, _traces: traces } }));

// Contrôles qualité déterministes (§ 10.2, couche 3), appliqués par
// indicateur et par zone. Une valeur qui échoue n'est ni corrigée ni
// devinée : elle est écartée et comptée. Le pipeline ETL n'a pas le droit
// de produire une valeur qu'il n'a pas lue.
const FENETRE_DEBUT = '2023';
const SEUIL_VARIATION_ANORMALE = 200;   // en %, entre deux périodes consécutives d'une même série

const obs = $input.all().map(i => i.json);
const incidents = obs[0]?._incidents ?? [];
const traces = obs[0]?._traces ?? [];
const retenues = [];
const ecartees = [];

const series = new Map();
for (const o of obs) {
  const cle = o.indicator_id + '|' + o.geo;
  if (!series.has(cle)) series.set(cle, []);
  series.get(cle).push(o);
}

for (const [, liste] of series) {
  liste.sort((a, b) => String(a.period).localeCompare(String(b.period)));
  let precedente = null;
  for (const o of liste) {
    const motifs = [];
    if (!Number.isFinite(o.value))                                    motifs.push('valeur non numérique');
    if (!/^\d{4}(-(\d{2}|T\d|S\d))?$/.test(String(o.period)))          motifs.push('format de période invalide');
    if (String(o.period).slice(0, 4) < FENETRE_DEBUT)                 motifs.push("hors fenêtre d'historique de trois ans");
    if (o.value < 0)                                                  motifs.push('valeur négative');
    if (precedente !== null && precedente !== 0) {
      const variation = Math.abs((o.value - precedente) / precedente * 100);
      if (variation > SEUIL_VARIATION_ANORMALE)                       motifs.push('variation anormale de ' + variation.toFixed(1) + ' %');
    }
    if (motifs.length) { ecartees.push({ indicateur: o.indicator_id, periode: o.period, geo: o.geo, motifs }); }
    else { const { _incidents, _traces, ...propre } = o; retenues.push(propre); precedente = o.value; }
  }
}

if (retenues.length === 0) {
  throw new Error('Toutes les observations ont été écartées : ' + JSON.stringify(ecartees.slice(0, 3)));
}

const bilan = {
  retenues: retenues.length,
  ecartees: ecartees.length,
  indicateurs: [...new Set(retenues.map(o => o.indicator_id))].sort(),
  detail_ecartees: ecartees.slice(0, 20),
  incidents,
  traces
};
return retenues.map(o => ({ json: { ...o, _bilan: bilan } }));
